// Check if internal_key is too short to contain a sequence number and type
if (internal_key.size() < 8) {
    return false;
}

const size_t n = internal_key.size();
const char* p = internal_key.data();

// The user key is all bytes except the last 8
*user_key = Slice(p, n - 8);

// Parse the sequence number and type from the last 8 bytes
const uint64_t num = leveldb::DecodeFixed64(p + n - 8);
*sequence = num >> 8;
*type = static_cast<uint8_t>(num & 0xff);

// Validate the type
if (*type > leveldb::kValueTypeForSeek) {
    return false;
}

// Validate the sequence number
if (*sequence > leveldb::kMaxSequenceNumber) {
    return false;
}

return true;

